// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address token) public {
        vm.assume(token != address(0));
        // First call: should succeed
        c.addReward(token);
        // Second call with same token: reference reverts (require "exists"), mutant does not
        try c.addReward(token) {
            // Mutant does not revert — property violated
            assertTrue(false);
        } catch {
            // Reference reverts — property holds
            assertTrue(true);
        }
    }
}

